import sys

def solve():
    # Read N and C from the first line
    try:
        line1 = sys.stdin.read().split()
    except Exception:
        return

    if not line1:
        return

    iterator = iter(line1)
    try:
        N = int(next(iterator))
        C = int(next(iterator))
        T = []
        for _ in range(N):
            T.append(int(next(iterator)))
    except StopIteration:
        return

    count = 1  # Always receive the 1st candy at the very first press
    current_time = T[0]

    # We have (N - 1) additional presses
    for i in range(1, N):
        next_press_time = T[i]
        elapsed = next_press_time - current_time

        if elapsed >= C:
            count += 1
        # Update the current time for the next iteration
        current_time = next_press_time

    print(count)

if __name__ == '__main__':
    solve()
